const { z } = require('zod');

/**
 * Zod Schema for individual API test cases generated by Gemini AI.
 * Strict validation ensures malformed or incomplete tests are rejected before storage or return.
 */
const TestCaseCategoryEnum = z.enum(['positive', 'negative', 'boundary', 'edge', 'security']);

const ExpectedResponseSchema = z.union([
  z.object({
    description: z.string().min(1, 'Expected response description is required'),
    schemaMatches: z.boolean().optional().default(true),
    bodyAssertions: z.array(z.string()).optional().default([]),
    expectedFields: z.array(z.string()).optional().default([]),
  }),
  z.string().min(1, 'Expected response description is required'),
]);

const TestCaseSchema = z.object({
  id: z.string().min(1, 'Unique test ID is required'),
  name: z.string().min(3, 'Test name must be at least 3 characters'),
  description: z.string().min(5, 'Test description must be at least 5 characters'),
  method: z.enum(['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS', 'HEAD']),
  path: z.string().min(1, 'Endpoint path is required'),
  headers: z.record(z.string()).optional().default({}),
  queryParams: z.record(z.union([z.string(), z.number(), z.boolean()])).optional().default({}),
  requestBody: z.any().optional().nullable(),
  expectedStatus: z.number().int().min(100).max(599, 'Expected HTTP status must be a valid status code (100-599)'),
  expectedResponse: ExpectedResponseSchema.optional(),
  expectedResponseConditions: z.array(z.string()).optional().default([]),
  category: TestCaseCategoryEnum,
});

/**
 * Root schema for Gemini test generation response payload
 */
const GeneratedTestsResponseSchema = z.object({
  endpointId: z.string().min(1, 'Endpoint ID is required'),
  endpointPath: z.string().min(1, 'Endpoint path is required'),
  method: z.string().min(1, 'HTTP method is required'),
  tests: z.array(TestCaseSchema).min(1, 'At least one test case must be generated'),
});

/**
 * Validation helper function
 */
function validateGeneratedTests(data) {
  return GeneratedTestsResponseSchema.safeParse(data);
}

module.exports = {
  TestCaseSchema,
  GeneratedTestsResponseSchema,
  validateGeneratedTests,
  TestCaseCategoryEnum,
};
